        return nums, 0
    mid = len(nums) // 2
    a, ca = inversions(nums[:mid])
    b, cb = inversions(nums[mid:])
    out, i, j, c = [], 0, 0, ca + cb
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1; c += len(a) - i
    return out + a[i:] + b[j:], c

